        {
           // input.Replace(oldChar,newChar);  
            input=input.Replace(oldChar,newChar);

        }

        private static void InsertLetterAtIndex(string input,int index,char letter)
        {
          //  input.Insert(index,letter.ToString());
            input+=letter;   
        }

        private static void Move(ref string input, int numberOfLettersToMove)
        {
            string firstPart = input.Substring(0, numberOfLettersToMove);
            string secondPart = input.Remove(0, numberOfLettersToMove);
            input += firstPart;
            input = secondPart + input ;
        }
    }
